package au.aumanet.app;
import org.json.*;
import java.util.*;

/** One bounded executor owns this repository. No GroupSession/PCM lock is taken by database work. */
final class GroupTextStore {
    static final int MAX_SCOPES=8,MAX_OUTBOX=16,MAX_HISTORY=128,MAX_LEDGER=512,MAX_ATTEMPTS=GroupMessageRetry.LIMIT;
    final GroupTextDatabase db;
    /** A rollback failure makes every read/write fail closed until a fresh process reopens SQLite. */
    private static final class Guarded implements GroupTextDatabase {
        final GroupTextDatabase delegate;boolean live=true;
        Guarded(GroupTextDatabase delegate){this.delegate=delegate;}
        private void require(){if(!live)throw new IllegalStateException("Private message storage requires restart after uncertain rollback; data was preserved");}
        public void exec(String sql,Object...args)throws Exception{require();delegate.exec(sql,args);}
        public List<Map<String,Object>> rows(String sql,String...args)throws Exception{require();return delegate.rows(sql,args);}
        public void begin()throws Exception{require();delegate.begin();}public void commit()throws Exception{require();delegate.commit();}public void rollback()throws Exception{require();delegate.rollback();}
        public void close()throws Exception{if(live){live=false;delegate.close();}}
        void poison(Throwable cause){if(live){live=false;try{delegate.close();}catch(Exception|Error close){cause.addSuppressed(close);}}}
    }
    private void poison(Throwable cause){((Guarded)db).poison(cause);}
    static final class Scope{
        final String group,self,key;Scope(String group,String self){this.group=GroupTextWire.id(group);this.self=GroupTextWire.pin(self);key=group+":"+self;}
    }
    interface Work<T>{T run()throws Exception;}
    static final class RevisionConflict extends Exception {RevisionConflict(){super("STORE_REVISION_CONFLICT");}}
    static final class NotAccepted extends Exception {NotAccepted(Exception cause){super(cause.getMessage(),cause);}}
    /** Only a pre-commit failure followed by successful rollback proves this request was not accepted. */
    private <T>T admissionTransaction(Work<T> work)throws Exception{
        boolean began=false,commitStarted=false;
        try{db.begin();began=true;T value=work.run();commitStarted=true;db.commit();return value;}
        catch(Exception|Error failure){if(began){try{db.rollback();}catch(Exception|Error uncertain){failure.addSuppressed(uncertain);poison(failure);throw failure;}}if(!commitStarted&&failure instanceof Exception)throw new NotAccepted((Exception)failure);throw failure;}
    }
    static GroupTextStore open(GroupTextDatabase database)throws Exception{try{return new GroupTextStore(database);}catch(Exception|Error failure){try{database.close();}catch(Exception close){failure.addSuppressed(close);}throw failure;}}
    GroupTextStore(GroupTextDatabase database)throws Exception{
        db=new Guarded(database);long version=number(db.rows("PRAGMA user_version").get(0).values().iterator().next());if(version!=0&&version!=1&&version!=2)throw new IllegalStateException("Unsupported saved message storage version; data was preserved");
        transaction(()->{db.exec("CREATE TABLE IF NOT EXISTS scopes (scope TEXT PRIMARY KEY,group_id TEXT NOT NULL,self_id TEXT NOT NULL,revision INTEGER NOT NULL,draft TEXT NOT NULL,last_wall INTEGER NOT NULL)");db.exec("CREATE TABLE IF NOT EXISTS entries (scope TEXT NOT NULL,sender TEXT NOT NULL,id TEXT NOT NULL,record TEXT NOT NULL,wire TEXT,inserted INTEGER NOT NULL,expiry INTEGER NOT NULL,pending INTEGER NOT NULL,PRIMARY KEY(scope,sender,id))");db.exec("CREATE TABLE IF NOT EXISTS ledger (scope TEXT NOT NULL,sender TEXT NOT NULL,id TEXT NOT NULL,digest TEXT,text_hash TEXT,membership_epoch INTEGER,message_expiry INTEGER,receipt TEXT,inserted INTEGER NOT NULL,expiry INTEGER NOT NULL,cancelled INTEGER NOT NULL,PRIMARY KEY(scope,sender,id))");db.exec("CREATE TABLE IF NOT EXISTS message_settings (scope TEXT PRIMARY KEY,shared INTEGER NOT NULL)");db.exec("PRAGMA user_version=2");return null;});
        // A persisted attempt marker already precedes every possible network emission.
        transaction(()->{for(Map<String,Object> row:db.rows("SELECT scope,sender,id,record FROM entries WHERE pending=1")){JSONObject record=new JSONObject(string(row,"record"));if(record.getInt("attempts")>0){record.put("state","unconfirmed").put("error","Previous attempt may have arrived; awaiting automatic retry or signed receipt");db.exec("UPDATE entries SET record=? WHERE scope=? AND sender=? AND id=?",record.toString(),string(row,"scope"),string(row,"sender"),string(row,"id"));}}return null;});
    }
    <T>T transaction(Work<T> work)throws Exception{db.begin();try{T value=work.run();db.commit();return value;}catch(Exception|Error failure){try{db.rollback();}catch(Exception|Error rollback){failure.addSuppressed(rollback);poison(failure);}throw failure;}}
    private static long number(Object value){if(!(value instanceof Number))throw new IllegalStateException("Saved message storage contains invalid numbers");return((Number)value).longValue();}
    private static String string(Map<String,Object> row,String key){Object value=row.get(key);if(!(value instanceof String))throw new IllegalStateException("Saved message storage contains invalid text");return(String)value;}
    private Map<String,Object> scope(Scope scope){return first(dbRows("SELECT * FROM scopes WHERE scope=?",scope.key));}
    private List<Map<String,Object>> dbRows(String sql,String...args){try{return db.rows(sql,args);}catch(Exception failure){throw new IllegalStateException("Private message storage could not be read",failure);}}
    private static Map<String,Object> first(List<Map<String,Object>> rows){return rows.isEmpty()?null:rows.get(0);}
    long revision(Scope scope){Map<String,Object> row=scope(scope);return row==null?0:number(row.get("revision"));}
    boolean clockUncertain(Scope scope,long now){Map<String,Object> row=scope(scope);return row!=null&&now<number(row.get("last_wall"))-GroupTextWire.CLOCK_SKEW;}
    String draft(Scope scope){Map<String,Object> row=scope(scope);return row==null?"":string(row,"draft");}
    private void ensure(Scope scope,long expected,long now)throws Exception{
        Map<String,Object> row=scope(scope);if(row==null){if(expected!=0)throw new RevisionConflict();if(number(db.rows("SELECT COUNT(*) AS n FROM scopes").get(0).get("n"))>=MAX_SCOPES)throw new IllegalStateException("Private message storage has reached its eight-group workspace limit; no other group's data was deleted");db.exec("INSERT INTO scopes VALUES(?,?,?,0,'',?)",scope.key,scope.group,scope.self,now);}
        else if(number(row.get("revision"))!=expected)throw new RevisionConflict();
    }
    private void bump(Scope scope,long now)throws Exception{if(revision(scope)>=9007199254740990L)throw new IllegalStateException("Message store revision exhausted");db.exec("UPDATE scopes SET revision=revision+1,last_wall=MAX(last_wall,?) WHERE scope=?",now,scope.key);}
    private void prune(Scope scope,long now)throws Exception{
        if(clockUncertain(scope,now))return;
        for(Map<String,Object> row:db.rows("SELECT sender,id,record FROM entries WHERE scope=? AND pending=1 AND expiry<=?",scope.key,Long.toString(now))){JSONObject record=new JSONObject(string(row,"record")).put("state","expired").put("error","Message expired under the experimental local-clock policy");db.exec("UPDATE entries SET record=?,pending=0,wire=NULL WHERE scope=? AND sender=? AND id=?",record.toString(),scope.key,string(row,"sender"),string(row,"id"));}
        db.exec("DELETE FROM entries WHERE scope=? AND pending=0 AND inserted<=?",scope.key,now-GroupTextWire.RETENTION);
        db.exec("DELETE FROM ledger WHERE scope=? AND expiry<=? AND NOT EXISTS (SELECT 1 FROM entries e WHERE e.scope=ledger.scope AND e.sender=ledger.sender AND e.id=ledger.id AND e.pending=1)",scope.key,now);
        db.exec("DELETE FROM entries WHERE scope=? AND pending=0 AND rowid NOT IN (SELECT rowid FROM entries WHERE scope=? AND pending=0 ORDER BY inserted DESC,id DESC LIMIT 128)",scope.key,scope.key);
    }
    private void ledgerCapacity(Scope scope)throws Exception{if(number(db.rows("SELECT COUNT(*) AS n FROM ledger WHERE scope=?",scope.key).get(0).get("n"))>=MAX_LEDGER)throw new IllegalStateException("The experimental message deduplication ledger is full; retained IDs were preserved");}
    void saveDraft(Scope scope,long expected,String text,long now)throws Exception{String valid=GroupTextWire.text(text,GroupTextWire.MAX_DRAFT,true);transaction(()->{ensure(scope,expected,now);prune(scope,now);db.exec("UPDATE scopes SET draft=? WHERE scope=?",valid,scope.key);bump(scope,now);return null;});}
    private Map<String,Object> ledger(Scope scope,String sender,String id){return first(dbRows("SELECT * FROM ledger WHERE scope=? AND sender=? AND id=?",scope.key,sender,id));}
    long receiptExpiry(Scope scope,String sender,String id,String digest){Map<String,Object> row=ledger(scope,sender,id);return row==null||!digest.equals(row.get("digest"))||row.get("message_expiry")==null?0:number(row.get("message_expiry"));}
    void knownSend(Scope scope,String id,long epoch)throws Exception{Map<String,Object> row=ledger(scope,scope.self,id);if(row==null||row.get("text_hash")==null)throw new IllegalStateException("This message ID was cancelled or retired before acceptance");if(number(row.get("membership_epoch"))!=epoch)throw new SecurityException("Message ID belongs to a different membership epoch");validateLedgerRecord(scope,id,row);String current=draft(scope);if(!current.isEmpty()&&!GroupTextWire.textHash(current).equals(row.get("text_hash")))throw new SecurityException("Message ID belongs to different accepted text");}
    private void validateLedgerRecord(Scope scope,String id,Map<String,Object> ledger)throws Exception{JSONObject record=find(scope,scope.self,id);if(record!=null&&(!operationHash(record).equals(ledger.get("text_hash"))||record.getLong("membershipEpoch")!=number(ledger.get("membership_epoch"))))throw new SecurityException("Saved message content/epoch conflicts with its immutable ledger");}
    JSONObject find(Scope scope,String sender,String id)throws Exception{Map<String,Object> row=first(db.rows("SELECT record FROM entries WHERE scope=? AND sender=? AND id=?",scope.key,sender,id));return row==null?null:new JSONObject(string(row,"record"));}
    String wire(Scope scope,String id)throws Exception{Map<String,Object> row=first(db.rows("SELECT wire FROM entries WHERE scope=? AND sender=? AND id=?",scope.key,scope.self,id));return row==null||row.get("wire")==null?null:string(row,"wire");}
    boolean containsOperation(Scope scope,String id){return ledger(scope,scope.self,id)!=null;}
    Set<String> activeAttemptKeys(long now)throws Exception{Set<String> keys=new HashSet<>();for(Map<String,Object> row:db.rows("SELECT scope,id FROM entries WHERE pending=1 AND expiry>?",Long.toString(now)))keys.add(string(row,"scope")+":"+string(row,"id"));return keys;}
    void enqueue(Scope scope,long expected,GroupTextWire.Message message,JSONObject sealed,long now)throws Exception{admissionTransaction(()->{
        ensure(scope,expected,now);prune(scope,now);if(containsOperation(scope,message.id))throw new IllegalStateException("Message ID was already accepted or cancelled");if(clockUncertain(scope,now))throw new IllegalStateException("Device clock moved backwards; the draft was preserved");if(message.image==null&&!draft(scope).equals(message.text))throw new IllegalStateException("Draft changed before acceptance");ledgerCapacity(scope);if(number(db.rows("SELECT COUNT(*) AS n FROM entries WHERE scope=? AND pending=1",scope.key).get(0).get("n"))>=MAX_OUTBOX)throw new IllegalStateException("The sixteen-message outbox is full; cancel an unsent operation first");
        JSONObject safe=GroupMessageSentContext.safeEnvelope(message,sealed,now);JSONObject record=record(message,now,"queued",0,0,new JSONArray(),"");JSONObject context=GroupMessageSentContext.verified(message,safe,now);if(context!=null)record.put("sentContext",context);db.exec("INSERT INTO ledger VALUES(?,?,?,?,?,?,?,NULL,?,?,0)",scope.key,message.sender,message.id,message.digest(),message.operationHash(),message.epoch,message.expires,now,now+GroupTextWire.RETENTION);db.exec("INSERT INTO entries VALUES(?,?,?,?,?,?,?,1)",scope.key,message.sender,message.id,record.toString(),safe.toString(),now,message.expires);if(message.image==null)db.exec("UPDATE scopes SET draft='' WHERE scope=?",scope.key);bump(scope,now);return null;
    });}
    JSONObject markAttempt(Scope scope,String id,long now)throws Exception{return transaction(()->{JSONObject record=find(scope,scope.self,id);if(record==null)throw new IllegalStateException("Message is no longer in the local outbox");if(clockUncertain(scope,now)||record.getLong("expiresAt")<=now||!Arrays.asList("queued","unconfirmed").contains(record.getString("state")))throw new IllegalStateException("Message cannot be retried");int attempts=record.getInt("attempts");if(attempts>=MAX_ATTEMPTS)throw new IllegalStateException("Explicit message attempt limit reached");if(attempts>0&&now-record.getLong("lastAttemptAt")<5000)throw new IllegalStateException("Wait for the current message attempt before retrying");record.put("attempts",attempts+1).put("lastAttemptAt",now).put("nextRetryAt",GroupMessageRetry.next(attempts+1,now,now)).put("attemptLimit",MAX_ATTEMPTS).put("state","unconfirmed").put("error",attempts+1>=MAX_ATTEMPTS?"Delivery remains unconfirmed after five attempts":"Awaiting signed durable receipts; retries pause while disconnected");db.exec("UPDATE entries SET record=? WHERE scope=? AND sender=? AND id=?",record.toString(),scope.key,scope.self,id);bump(scope,now);return record;});}
    List<JSONObject> pending(Scope scope,long now)throws Exception{
        transaction(()->{prune(scope,now);return null;});
        List<JSONObject> result=new ArrayList<>();for(Map<String,Object> row:db.rows("SELECT record FROM entries WHERE scope=? AND pending=1 ORDER BY inserted,id LIMIT 16",scope.key))result.add(new JSONObject(string(row,"record")));return result;
    }
    void requireRevision(Scope scope,long expected)throws RevisionConflict{if(revision(scope)!=expected)throw new RevisionConflict();}
    /** First commit precedes receipt signing. Duplicate content cannot replace an accepted ID. */
    private static boolean measuredRadio(JSONArray values){if(values==null||values.length()>2)return false;for(int i=0;i<values.length();i++){JSONObject value=values.optJSONObject(i);if(value==null||!"available".equals(value.optString("status")))continue;Object raw=value.opt("rssiDbm");if(raw instanceof Number){double n=((Number)raw).doubleValue();if(Double.isFinite(n)&&n==Math.rint(n)&&n>=-127&&n<=-1)return true;}}return false;}
    static final class Incoming {final long storedAt;final boolean firstCommit;Incoming(long storedAt,boolean firstCommit){this.storedAt=storedAt;this.firstCommit=firstCommit;}}
    long incoming(Scope scope,GroupTextWire.Message message,long now)throws Exception{return incomingCommitted(scope,message,now).storedAt;}
    Incoming incomingCommitted(Scope scope,GroupTextWire.Message message,long now)throws Exception{return incomingCommitted(scope,message,null,now);}
    Incoming incomingCommitted(Scope scope,GroupTextWire.Message message,JSONObject sealed,long now)throws Exception{return incomingCommitted(scope,message,sealed,now,null);}
    Incoming incomingCommitted(Scope scope,GroupTextWire.Message message,JSONObject sealed,long now,JSONArray radio)throws Exception{return transaction(()->{
        ensure(scope,revision(scope),now);prune(scope,now);Map<String,Object> previous=ledger(scope,message.sender,message.id);if(previous!=null){if(!message.digest().equals(previous.get("digest")))throw new SecurityException("Message ID conflicts with accepted content");return new Incoming(number(previous.get("inserted")),false);}
        if(clockUncertain(scope,now))throw new IllegalStateException("Device clock moved backwards; receipt was not issued");ledgerCapacity(scope);JSONObject record=record(message,now,"received",0,0,new JSONArray().put(scope.self),"");JSONObject context=sealed==null?null:GroupMessageSentContext.verified(message,sealed,now);if(context!=null)record.put("sentContext",context);if(measuredRadio(radio))record.put("radioAtReceipt",new JSONObject().put("receivedAt",now).put("signals",new JSONArray(radio.toString())));db.exec("INSERT INTO ledger VALUES(?,?,?,?,?,?,?,NULL,?,?,0)",scope.key,message.sender,message.id,message.digest(),message.operationHash(),message.epoch,message.expires,now,now+GroupTextWire.RETENTION);db.exec("INSERT INTO entries VALUES(?,?,?,?,NULL,?,?,0)",scope.key,message.sender,message.id,record.toString(),now,message.expires);prune(scope,now);bump(scope,now);return new Incoming(now,true);
    });}
    JSONObject receipt(Scope scope,String sender,String id)throws Exception{Map<String,Object> row=ledger(scope,sender,id);return row==null||row.get("receipt")==null?null:new JSONObject(string(row,"receipt"));}
    void storeReceipt(Scope scope,GroupTextWire.Message message,JSONObject receipt,long now)throws Exception{transaction(()->{Map<String,Object> row=ledger(scope,message.sender,message.id);if(row==null||!message.digest().equals(row.get("digest")))throw new SecurityException("Durable incoming commit is missing");if(row.get("receipt")==null){db.exec("UPDATE ledger SET receipt=? WHERE scope=? AND sender=? AND id=?",receipt.toString(),scope.key,message.sender,message.id);bump(scope,now);}return null;});}
    void acknowledge(Scope scope,GroupTextWire.Receipt receipt,long now)throws Exception{if(!scope.group.equals(receipt.group)||!scope.self.equals(receipt.sender))throw new SecurityException("Receipt belongs to a different message scope");transaction(()->{JSONObject record=find(scope,scope.self,receipt.id);Map<String,Object> stored=ledger(scope,scope.self,receipt.id);if(record==null||record.getLong("membershipEpoch")!=receipt.epoch||record.getLong("expiresAt")<=now||record.getInt("attempts")==0||stored==null||!receipt.digest.equals(stored.get("digest"))||!Arrays.asList("queued","unconfirmed").contains(record.getString("state")))return null;JSONArray recipients=record.getJSONArray("recipients"),acks=record.getJSONArray("acknowledgedBy");List<String> frozen=strings(recipients),accepted=strings(acks);if(!frozen.contains(receipt.recipient))throw new SecurityException("Receipt recipient was not frozen for this operation");if(accepted.contains(receipt.recipient))return null;accepted.add(receipt.recipient);Collections.sort(accepted);boolean delivered=accepted.size()==frozen.size();record.put("acknowledgedBy",new JSONArray(accepted)).put("state",delivered?"delivered":"unconfirmed").put("error",delivered?"":"Some frozen recipients have not confirmed durable receipt");db.exec("UPDATE entries SET record=?,pending=?,wire=CASE WHEN ?=0 THEN wire ELSE wire END WHERE scope=? AND sender=? AND id=?",record.toString(),delivered?0:1,delivered?0:1,scope.key,scope.self,receipt.id);prune(scope,now);bump(scope,now);return null;});}
    void cancel(Scope scope,long expected,String id,long now)throws Exception{GroupTextWire.id(id);transaction(()->{ensure(scope,expected,now);prune(scope,now);Map<String,Object> known=ledger(scope,scope.self,id);JSONObject existing=find(scope,scope.self,id);if(known!=null&&known.get("text_hash")!=null)validateLedgerRecord(scope,id,known);if(existing!=null&&!Arrays.asList("queued","unconfirmed").contains(existing.getString("state")))throw new IllegalStateException("Only pending local operations can be cancelled");if(known==null){ledgerCapacity(scope);long retained=Math.max(now,number(scope(scope).get("last_wall")));db.exec("INSERT INTO ledger VALUES(?,?,?,NULL,NULL,NULL,NULL,NULL,?,?,1)",scope.key,scope.self,id,retained,retained+GroupTextWire.RETENTION);}else db.exec("UPDATE ledger SET cancelled=1 WHERE scope=? AND sender=? AND id=?",scope.key,scope.self,id);JSONObject record=find(scope,scope.self,id);if(record!=null&&Arrays.asList("queued","unconfirmed").contains(record.getString("state"))){record.put("state","cancelled").put("error","Future attempts cancelled; in-flight delivery cannot be retracted");db.exec("UPDATE entries SET record=?,pending=0,wire=NULL WHERE scope=? AND sender=? AND id=?",record.toString(),scope.key,scope.self,id);}bump(scope,now);return null;});}
    void clearHistory(Scope scope,long expected,long now)throws Exception{transaction(()->{ensure(scope,expected,now);prune(scope,now);db.exec("DELETE FROM entries WHERE scope=? AND pending=0",scope.key);bump(scope,now);return null;});}
    JSONObject lookup(Scope scope,String id,long now)throws Exception{Map<String,Object> known=ledger(scope,scope.self,GroupTextWire.id(id));JSONObject result=new JSONObject().put("schema","aumanet.group-message-lookup.v1").put("source","device").put("groupId",scope.group).put("selfId",scope.self).put("id",id).put("found",known!=null).put("retired",false).put("cancelled",known!=null&&number(known.get("cancelled"))!=0);if(known!=null){if(known.get("text_hash")!=null)validateLedgerRecord(scope,id,known);JSONObject row=find(scope,scope.self,id);result.put("retired",row==null);if(known.get("text_hash")!=null)result.put("textSha256",string(known,"text_hash")).put("membershipEpoch",number(known.get("membership_epoch")));if(row!=null)result.put("record",view(row,now,0,false));}return result;}
    boolean newIntentRoom(Scope scope,long now)throws Exception{
        if(clockUncertain(scope,now))return false;
        if(scope(scope)==null&&number(db.rows("SELECT COUNT(*) AS n FROM scopes").get(0).get("n"))>=MAX_SCOPES)return false;
        long ledger=number(db.rows("SELECT COUNT(*) AS n FROM ledger WHERE scope=? AND (expiry>? OR EXISTS (SELECT 1 FROM entries e WHERE e.scope=ledger.scope AND e.sender=ledger.sender AND e.id=ledger.id AND e.pending=1 AND e.expiry>?))",scope.key,Long.toString(now),Long.toString(now)).get(0).get("n"));
        long pending=number(db.rows("SELECT COUNT(*) AS n FROM entries WHERE scope=? AND pending=1 AND expiry>?",scope.key,Long.toString(now)).get(0).get("n"));
        return ledger<MAX_LEDGER&&pending<MAX_OUTBOX;
    }
    JSONObject snapshot(Scope scope,long epoch,long now,boolean connected,boolean canSend)throws Exception{
        JSONArray history=new JSONArray(),outbox=new JSONArray();List<JSONObject> old=new ArrayList<>();boolean uncertain=clockUncertain(scope,now);
        for(Map<String,Object> row:db.rows("SELECT record FROM entries WHERE scope=? ORDER BY inserted ASC,id ASC",scope.key)){JSONObject record=view(new JSONObject(string(row,"record")),now,epoch,canSend&&!uncertain);if(Arrays.asList("queued","unconfirmed").contains(record.getString("state")))outbox.put(record);else old.add(record);}for(int i=Math.max(0,old.size()-MAX_HISTORY);i<old.size();i++)history.put(old.get(i));
        return new JSONObject().put("storeRevision",revision(scope)).put("draft",draft(scope)).put("history",history).put("outbox",outbox).put("clockUncertain",uncertain).put("connected",connected).put("canSend",canSend&&!uncertain&&newIntentRoom(scope,now));
    }
    static String operationHash(JSONObject row)throws Exception{return GroupTextWire.textHash(row.getString("text")+("image".equals(row.optString("kind"))?"\0"+row.getJSONObject("image").getString("sourceSha256"):""));}
    Set<String> imageReferences()throws Exception{Set<String> result=new HashSet<>();for(Map<String,Object> row:db.rows("SELECT scope,sender,id,record FROM entries")){JSONObject record=new JSONObject(string(row,"record"));if("image".equals(record.optString("kind")))result.add(GroupTextWire.hash((string(row,"scope")+":"+string(row,"sender")+":"+string(row,"id")).getBytes(java.nio.charset.StandardCharsets.US_ASCII)));}return result;}
    boolean liveImageOffers(Scope scope,long now)throws Exception{for(Map<String,Object> row:db.rows("SELECT record FROM entries WHERE scope=? AND expiry>? AND wire IS NOT NULL",scope.key,Long.toString(now))){JSONObject record=new JSONObject(string(row,"record"));if("image".equals(record.optString("kind"))&&!Arrays.asList("cancelled","expired").contains(record.optString("state")))return true;}return false;}
    boolean knownMessage(Scope scope,String sender,String id){return ledger(scope,sender,id)!=null;}
    boolean historyShared(Scope scope)throws Exception{List<Map<String,Object>> rows=db.rows("SELECT shared FROM message_settings WHERE scope=?",scope.key);return !rows.isEmpty()&&number(rows.get(0).get("shared"))==1;}
    void importHistory(Scope scope,GroupTextWire.Message message,JSONObject sealed,boolean historical,long now)throws Exception{final JSONObject safe=GroupMessageSentContext.safeEnvelope(message,sealed,now);transaction(()->{ensure(scope,revision(scope),now);prune(scope,now);Map<String,Object> previous=ledger(scope,message.sender,message.id);if(previous!=null){if(!message.digest().equals(previous.get("digest")))throw new SecurityException("History ID conflicts with durable content");return null;}if(clockUncertain(scope,now))throw new IllegalStateException("Device clock moved backwards; history import paused");ledgerCapacity(scope);JSONObject record=record(message,now,"received",0,0,historical?new JSONArray():new JSONArray().put(scope.self),"").put("historical",historical);JSONObject context=GroupMessageSentContext.verified(message,safe,now);if(context!=null)record.put("sentContext",context);db.exec("INSERT INTO ledger VALUES(?,?,?,?,?,?,?,NULL,?,?,0)",scope.key,message.sender,message.id,message.digest(),message.operationHash(),message.epoch,message.expires,now,now+GroupTextWire.RETENTION);db.exec("INSERT INTO entries VALUES(?,?,?,?,?,?,?,0)",scope.key,message.sender,message.id,record.toString(),safe.toString(),now,message.expires);prune(scope,now);bump(scope,now);return null;});}
    void configureHistory(Scope scope,long expected,boolean shared,long now)throws Exception{transaction(()->{ensure(scope,expected,now);db.exec("INSERT OR REPLACE INTO message_settings VALUES(?,?)",scope.key,shared?1:0);bump(scope,now);return null;});}
    void retainWire(Scope scope,GroupTextWire.Message message,JSONObject sealed)throws Exception{db.exec("UPDATE entries SET wire=COALESCE(wire,?) WHERE scope=? AND sender=? AND id=?",GroupMessageSentContext.safeEnvelope(message,sealed,System.currentTimeMillis()).toString(),scope.key,message.sender,message.id);}
    JSONObject sealed(Scope scope,String sender,String id)throws Exception{List<Map<String,Object>> rows=db.rows("SELECT wire FROM entries WHERE scope=? AND sender=? AND id=?",scope.key,sender,id);return rows.isEmpty()||rows.get(0).get("wire")==null?null:new JSONObject(string(rows.get(0),"wire"));}
    List<JSONObject> historyWires(Scope scope,long now)throws Exception{List<JSONObject> result=new ArrayList<>();for(Map<String,Object> row:db.rows("SELECT wire FROM entries WHERE scope=? AND expiry>? AND wire IS NOT NULL AND pending=0 ORDER BY inserted DESC,id DESC LIMIT 128",scope.key,Long.toString(now)))result.add(new JSONObject(string(row,"wire")));return result;}
    void imageProgress(Scope scope,String sender,String id,String state,int received,long now)throws Exception{transaction(()->{JSONObject row=find(scope,sender,id);if(row==null||!"image".equals(row.optString("kind")))throw new IllegalStateException("Image message no longer exists");JSONObject image=row.getJSONObject("image");if(received<0||received>image.getInt("byteLength"))throw new IllegalArgumentException("Invalid image progress");image.put("state",state).put("receivedBytes",received);db.exec("UPDATE entries SET record=? WHERE scope=? AND sender=? AND id=?",row.toString(),scope.key,sender,id);bump(scope,now);return null;});}
    /** Durable image rows ARE the queue. Completed/cancelled rows never occupy
     * the candidate limit, so older retained placeholders eventually advance. */
    List<JSONObject> imageDownloadQueue(Scope scope,long now)throws Exception{
        List<JSONObject> result=new ArrayList<>();for(Map<String,Object> row:db.rows("SELECT record FROM entries WHERE scope=? AND sender<>? AND expiry>? ORDER BY inserted DESC,id DESC LIMIT 128",scope.key,scope.self,Long.toString(now))){JSONObject record=new JSONObject(string(row,"record"));if(!"image".equals(record.optString("kind")))continue;String state=record.getJSONObject("image").optString("state","placeholder");if(!Arrays.asList("placeholder","downloading").contains(state))continue;if(record.getJSONObject("image").optLong("nextAutoAt")>now)continue;result.add(record);}return result;
    }
    void imageFailure(Scope scope,String sender,String id,int failures,boolean terminal,long now)throws Exception{imageFailure(scope,sender,id,failures,terminal,0,now);}
    void imageFailure(Scope scope,String sender,String id,int failures,boolean terminal,long next,long now)throws Exception{transaction(()->{JSONObject row=find(scope,sender,id);if(row==null)return null;row.getJSONObject("image").put("failureCount",failures).put("nextAutoAt",next);if(terminal)row.getJSONObject("image").put("state","failed");db.exec("UPDATE entries SET record=? WHERE scope=? AND sender=? AND id=?",row.toString(),scope.key,sender,id);bump(scope,now);return null;});}
    List<JSONObject> historyRows(Scope scope)throws Exception{List<JSONObject> result=new ArrayList<>();for(Map<String,Object> row:db.rows("SELECT record FROM entries WHERE scope=? AND pending=0",scope.key))result.add(new JSONObject(string(row,"record")));return result;}
    static List<String> strings(JSONArray list)throws Exception{List<String> result=new ArrayList<>();for(int i=0;i<list.length();i++)result.add(GroupTextWire.string(new JSONObject().put("v",list.get(i)),"v"));return result;}
    private static JSONObject record(GroupTextWire.Message message,long stored,String state,int attempts,long last,JSONArray acks,String error)throws Exception{return new JSONObject().put("kind",message.image==null?"text":"image").put("image",message.image==null?JSONObject.NULL:message.image.json().put("state","placeholder").put("receivedBytes",0).put("totalBytes",message.image.bytes)).put("id",message.id).put("senderId",message.sender).put("text",message.text).put("createdAt",message.created).put("storedAt",stored).put("expiresAt",message.expires).put("membershipEpoch",message.epoch).put("recipients",new JSONArray(message.recipients)).put("acknowledgedBy",acks).put("attempts",attempts).put("lastAttemptAt",last).put("state",state).put("error",error).put("retryable",false).put("nextRetryAt",attempts==0?stored:GroupMessageRetry.next(attempts,last,stored)).put("attemptLimit",MAX_ATTEMPTS);}
    private static JSONObject view(JSONObject record,long now,long epoch,boolean canSend)throws Exception{record.put("attemptLimit",MAX_ATTEMPTS).put("nextRetryAt",Arrays.asList("queued","unconfirmed").contains(record.getString("state"))?GroupMessageRetry.next(record.getInt("attempts"),record.getLong("lastAttemptAt"),now):0);String state=record.getString("state");boolean pending=Arrays.asList("queued","unconfirmed").contains(state);if(pending&&record.getLong("expiresAt")<=now){record.put("state","expired").put("error","Message expired under the experimental local-clock policy");pending=false;}boolean same=record.getLong("membershipEpoch")==epoch;record.put("retryable",pending&&canSend&&same&&record.getInt("attempts")<MAX_ATTEMPTS&&(record.getInt("attempts")==0||now-record.getLong("lastAttemptAt")>=5000));if(pending&&epoch>0&&!same)record.put("error","Group membership changed; cancel or compose a new message");return record;}
}
